265	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
266	  // One place decides, and the env var wins. `KODELY_ENGINE=sdk` pins every
267	  // run to the SDK; when it is at its `api` default the caller may opt an
