272	  if (engine === "sdk") {
273	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
274	    // authenticated this must fail loudly rather than quietly spend money on
275	    // the metered key the operator asked not to use.
276	    const { runAgentSdk } = await import("./agent-sdk");
277	    yield* runAgentSdk(opts, SYSTEM);
278	    return;
279	  }
280	
281	  const model = MODELS.builder;
282	  // Effort is the sharpest cost lever we have: a first build is a blank-page
283	  // design problem and earns `high`, while a targeted tweak lands the same
284	  // result at `medium` for a fraction of the thinking tokens.
285	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
286	
287	  const messages: Anthropic.MessageParam[] = [];
288	  for (const turn of opts.history) {
289	    messages.push({ role: turn.role, content: turn.content });
290	  }
291	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
292	  if (opts.image) {
293	    messages.push({
294	      role: "user",
295	      content: [
296	        {
