303	        },
304	        { type: "text", text: `${requestText}\n\n(A reference image is attached above — use it as visual/style guidance for the site.)` },
305	      ],
306	    });
307	  } else {
308	    messages.push({ role: "user", content: requestText });
309	  }
310	
311	  const totals = {
312	    inputTokens: 0,
313	    outputTokens: 0,
314	    cacheReadTokens: 0,
315	    cacheWriteTokens: 0,
316	  };
317	
318	  // Bounded so a confused model can never bill the user for an endless loop.
319	  const MAX_TURNS = 8;
320	
321	  for (let turn = 0; turn < MAX_TURNS; turn++) {
322	    if (opts.signal?.aborted) return;
323	
324	    const stream = anthropic.messages.stream(
325	      {
326	        model,
327	        max_tokens: 32_000,
328	        thinking: { type: "adaptive" },
329	        output_config: { effort },
330	        system: [{ type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } }],
331	        tools: TOOLS,
332	        messages,
333	      },
334	      { signal: opts.signal },
335	    );
336	
337	    for await (const event of stream) {
338	      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
