340	      }
341	    }
342	
343	    const message = await stream.finalMessage();
344	    totals.inputTokens += message.usage.input_tokens ?? 0;
345	    totals.outputTokens += message.usage.output_tokens ?? 0;
346	    totals.cacheReadTokens += message.usage.cache_read_input_tokens ?? 0;
347	    totals.cacheWriteTokens += message.usage.cache_creation_input_tokens ?? 0;
348	
349	    if (message.stop_reason === "refusal") {
350	      throw new Error(
351	        "The request was declined. Try describing the site you want in different terms.",
352	      );
353	    }
354	
355	    const toolUses = message.content.filter(
356	      (b): b is Anthropic.ToolUseBlock => b.type === "tool_use",
357	    );
358	
359	    if (toolUses.length === 0) {
360	      yield { type: "usage", model, ...totals };
361	      return;
362	    }
363	
364	    messages.push({ role: "assistant", content: message.content });
365	
366	    const results: Anthropic.ToolResultBlockParam[] = [];
367	    for (const use of toolUses) {
368	      const input = use.input as {
369	        path?: string;
370	        content?: string;
371	        query?: string;
372	        kind?: string;
373	        limit?: number;
374	      };
375	
376	      // Handled before the path check below — this is the one tool that takes
377	      // no path, and running it through normalizePath would reject it outright.
378	      if (use.name === "find_assets") {
379	        yield { type: "progress", text: "Picking out icons and artwork" };
380	        const matches = findAssets(input.query ?? "", {
381	          kind: input.kind as AssetKind | undefined,
382	          limit: Math.min(Math.max(input.limit ?? 6, 1), 12),
383	        });
384	        results.push({
385	          type: "tool_result",
386	          tool_use_id: use.id,
387	          content: formatMatchesForTool(matches),
388	        });
389	        continue;
390	      }
391	
392	      const path = normalizePath(input.path ?? "");
393	
394	      if (!path) {
395	        results.push({
396	          type: "tool_result",
397	          tool_use_id: use.id,
398	          content: `Rejected: '${input.path}' is not a valid project-relative path.`,
399	          is_error: true,
400	        });
401	        continue;
402	      }
403	
404	      // Narrate before applying, so the line appears while the write is
405	      // happening rather than after it lands.
406	      const line = narrateTool(use.name, { path });
407	      if (line) yield { type: "progress", text: line };
408	
409	      if (use.name === "write_file") {
410	        const ok = await opts.onWrite(path, input.content ?? "");
411	        if (ok) yield { type: "file", path, action: "write" };
412	        results.push({
413	          type: "tool_result",
414	          tool_use_id: use.id,
415	          content: ok ? `Wrote ${path}.` : `Could not write ${path}.`,
416	          is_error: !ok,
417	        });
418	      } else if (use.name === "delete_file") {
419	        const ok = await opts.onDelete(path);
