function lit(text) {
  return text.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

const KERNEL = [
  ["src/kernel/types.ts", "The schema language: FieldKind, Field, Collection, AppSchema, Row, Snapshot.", "collectionByKey, fieldByName"],
