  ["src/kernel/AppShell.tsx", "Header, responsive nav, theme toggle, and the non-dismissible local-storage notice.", "AppShell"],
  ["src/kernel/FieldControl.tsx", "Renders one schema field as the right labelled control.", "FieldControl"],
  ["src/kernel/CollectionList.tsx", "List view for any collection: search, filter, sort, CSV export, table on desktop and cards on mobile.", "CollectionList"],
  ["src/kernel/RecordDetail.tsx", "Detail view for any record, with related child collections and delete confirmation.", "RecordDetail, MissingRecord"],
  ["src/kernel/RecordForm.tsx", "Create and edit form generated from the schema.", "RecordForm"],
  ["src/kernel/DataSettings.tsx", "Backup, restore, delete-everything, and the plain-words explanation of where data lives.", "DataSettings"],
  ["src/kernel/AppRoutes.tsx", "Maps the current route to a kernel screen.", "AppRoutes"],
];

const APPFILES = [
  ["index.html", "Document head: title, description and OG tags. Rewrite these for the real app.", true],
  ["src/main.tsx", "React entry point. Nothing to change here.", false],
  ["src/index.css", "Tailwind import, the dark-mode variant, and the font stack.", true],
  ["src/App.tsx", "Wiring: store, providers, shell, routes, dashboard.", true],
  ["src/app/schema.ts", "THE APP'S DATA MODEL. Collections and fields — edit this first.", true],
  ["src/app/branding.ts", "App name, tagline and the localStorage namespace.", true],
  ["src/app/Dashboard.tsx", "The one screen the kernel cannot generate: what this app thinks matters.", true],
];

function emit(entries, kind) {
  const lines = [];
  for (const entry of entries) {
    const [file, purpose] = entry;
    const editable = kind === "app" ? entry[2] : false;
    const exports = kind === "kernel" ? entry[2] : "";
    const body = readFileSync(path.join(APP, file), "utf8");
    lines.push("  " + JSON.stringify(file) + ": {");
    lines.push("    purpose: " + JSON.stringify(purpose) + ",");
    if (exports) lines.push("    exports: " + JSON.stringify(exports) + ",");
    lines.push("    editable: " + editable + ",");
    lines.push("    content: `" + lit(body) + "`,");
    lines.push("  },");
  }
  return lines.join("\n");
}

